"""Experiment 54 / D7: concurrent agency/sector portfolio pressure."""
from __future__ import annotations
import sys
import pandas as pd
from backend.app.ml.experiments.nextgen_common import fit_features,run_cli
EXPERIMENT_ID="exp_54";EXPERIMENT_SEQUENCE=54;MARKER="EXP54";EXPERIMENT_NAME="Concurrent portfolio pressure Delay features";EXPERIMENT_SCOPE="delay";CHANGED_DIMENSION="concurrent_portfolio_pressure_features"
FEATURES=["exp54_agency_live_projects","exp54_sector_live_projects","exp54_agency_mean_slippage","exp54_sector_mean_slippage","exp54_agency_mean_cost_pressure","exp54_sector_mean_cost_pressure","exp54_agency_mean_spend_ratio","exp54_sector_mean_spend_ratio"]
def engineer_portfolio_pressure(frame:pd.DataFrame)->pd.DataFrame:
 out=frame.copy();month=pd.to_datetime(out["snapshot_date"],errors="coerce").dt.to_period("M").astype("string");agency=out.get("implementing_agency",pd.Series("<NA>",index=out.index)).astype("string").fillna("<NA>").str.lower().str.replace(r"[^a-z0-9]+"," ",regex=True).str.strip();sector=out.get("sector",pd.Series("<NA>",index=out.index)).astype("string").fillna("<NA>").str.lower().str.replace(r"[^a-z0-9]+"," ",regex=True).str.strip();slip=pd.to_numeric(out.get("schedule_slippage_days"),errors="coerce");cost=pd.to_numeric(out.get("cost_escalation_percentage"),errors="coerce");spend=pd.to_numeric(out.get("expenditure_ratio"),errors="coerce")
 out["exp54_agency_live_projects"]=out["canonical_project_id"].groupby([month,agency]).transform("nunique").astype(float);out["exp54_sector_live_projects"]=out["canonical_project_id"].groupby([month,sector]).transform("nunique").astype(float);out["exp54_agency_mean_slippage"]=slip.groupby([month,agency]).transform("mean").fillna(0);out["exp54_sector_mean_slippage"]=slip.groupby([month,sector]).transform("mean").fillna(0);out["exp54_agency_mean_cost_pressure"]=cost.groupby([month,agency]).transform("mean").fillna(0);out["exp54_sector_mean_cost_pressure"]=cost.groupby([month,sector]).transform("mean").fillna(0);out["exp54_agency_mean_spend_ratio"]=spend.groupby([month,agency]).transform("mean").fillna(0);out["exp54_sector_mean_spend_ratio"]=spend.groupby([month,sector]).transform("mean").fillna(0);return out
def fit_experiment(**kwargs):return fit_features(exp_id=EXPERIMENT_ID,name=EXPERIMENT_NAME,dimension=CHANGED_DIMENSION,scope="delay",engineer=engineer_portfolio_pressure,delay_new=FEATURES,details={"peer_definition":"same snapshot month within normalized agency/sector; observable covariates only"},**kwargs)
if __name__=="__main__":run_cli(sys.modules[__name__])
